mapper.insert:
INSERT INTO ledger_entries (
    transaction_id, entry_seq, account_type, account_ref_id, direction, amount, balance_after, created_at
) VALUES (
    #{transactionId}, #{entrySeq}, #{accountType}, #{accountRefId}, #{direction}, #{amount}, #{balanceAfter}, NOW()
)

mapper.select:
SELECT COALESCE(SUM(CASE WHEN direction = 'CREDIT' THEN amount ELSE -amount END), 0)
FROM ledger_entries
WHERE account_type = #{accountType}
  AND account_ref_id = #{accountRefId}
